settings.css:
.mapplic-thumbnail > img {
tfilter: grayscale(100%);
topacity: 0.5;
}

.mapplic-dir-item:hover .mapplic-thumbnail img,
.mapplic-dir-item.mapplic-active .mapplic-thumbnail img {
tfilter: grayscale(0%);
topacity: 1;
}

.mapplic-action-phone, .mapplic-popup-link {
    display: none !important;
}

.mapplic-thumbnail > img {
    object-fit: contain;
}

.mapplic-popup-image > img {
    object-fit: contain;
    padding: 8px;
    box-sizing: border-box;
}

.mapplic-popup-image {
    flex-basis: 60%;
    flex-grow: 0;
}

.mapplic-tooltip {
    max-width: calc(500px) !important;
}
.mapplic-dir {
    height: 51vh;
    border: solid 1px #cccccc;
    border-radius: 10px;
    background-color: var(--mapplic-bg-default);
    border-color: var(--mapplic-border-faint);
    box-shadow: 0 4px 8px #00000005;
}

@media only screen and (max-width: 480px) {
  .mapplic-tooltip {
        max-width: calc(250px) !important;
        flex-direction: column;
    }
    .mapplic-tooltip-mini .mapplic-popup-image {
        display: flex !important;
        width: 100%;
    }
}
